insert into tasks (id,powertrain_id,title,category,group_name,aliases,live,time_label,difficulty) values ('short-shifter','bpy','Short shifter install','Drivetrain',null,array['short shifter','shifter','dieselgeek','sigma','shift cables','throw']::text[],true,'1.5–2 hr',2) on conflict (id) do update set title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,title,category,group_name,aliases,live,time_label,difficulty) values ('battery','bpy','Battery replacement','Electrical',null,array['battery','optima','odyssey','agm','slow crank','h6']::text[],true,'30 min',1) on conflict (id) do update set title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,title,category,group_name,aliases,live,time_label,difficulty) values ('headlights','bpy','Headlight bulbs & housings','Electrical',null,array['headlight','bulb','h7','d2s','xenon','hid','low beam','fogged lens']::text[],true,'1–1.5 hr',2) on conflict (id) do update set title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('short-shifter',$j${"id": "short-shifter", "title": "Short shifter install", "fits": "2006 VW GTI · 6-speed manual (02Q)", "heroId": "shifter-hero", "alsoFits": "Any 02M/02Q/MQ350 6-speed: Mk5–Mk7 GTI/Golf/Jetta/R, A3, TT", "category": "Drivetrain", "kind": "upgrade", "glance": {"timeFirst": "1.5–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$250–350", "risk": "Adjustment is everything; a badly adjusted shifter grinds gears", "why": "The factory shifter has a long throw and rubber-isolated cable ends that add slop. A short-shift kit swaps the lever on top of the transmission for a shorter one and the cable ends for solid ones, so each shift is shorter and more direct. It's the mod you feel every single time you drive.", "note": "Owners who'd never touched a transmission report two hours with the PDF printed out. Adjustment is where the time goes."}, "heroCap": "Two cables from the cabin shifter to two levers on top of the transmission. The kit replaces the front-to-back lever (shorter arm = shorter throw) and the cable ends. Adjustment locks the transmission in neutral and pins the cabin shifter, then sets the cables between them.", "lifespan": {"title": "When owners do this", "headline": ["Often the first interior mod; any time"], "earliest": null, "detail": "Nothing wears out to force it. Worn shifter bushings in the cabin base do make the stock shifter sloppy by 100k, and Dieselgeek says to replace those first or the new shifter can't be adjusted properly.", "factors": ["Sloppy or vague stock shifter", "You want shorter throws", "Doing a clutch (cables are off anyway)"], "inspect": ["Wiggle the shift knob side to side in neutral: excessive play is the bushings, not the cables"], "confidence": {"level": "community", "n": 3, "note": "Vendor guidance and owner reports."}}, "should": {"yesIf": ["Long, vague throws bother you", "Shifter has side-to-side slop in neutral", "You're pulling the airbox anyway for another job"], "codes": [], "notes": ["Set expectations: a short shifter is shorter and more direct, and also a bit notchier with a heavier throw. Dieselgeek says so on their own product page. If you want buttery, this isn't it.", "Check the cabin shifter bushings before you buy. If the knob has a lot of side-to-side play in neutral, the base bushings are worn and the kit won't adjust right until they're replaced (Dieselgeek sells them; ten-minute job under the console trim)."], "confidence": {"level": "high", "n": 3, "note": "Consistent across the vendor and two owner DIYs."}}, "parts": [{"tier": "aftermarket", "name": "Short shift kit", "pn": "see options below", "note": "Lever, cable ends, hardware, locking pin", "price": "$250–350", "links": []}, {"tier": "aftermarket", "name": "Shifter base bushings + aluminium side-to-side cable end", "pn": "Dieselgeek", "note": "If the cabin shifter has play", "price": "$40–80", "links": []}, {"tier": "oe", "name": "Lithium or silicone grease for the cable ends", "pn": "—", "note": "", "price": "$5", "links": []}], "aftermarket": [{"name": "Dieselgeek Sigma 6", "note": "The reference kit for the 02Q: all-aluminium front-to-back cable end on a steel spherical bearing, lifetime guarantee, and the only kit with a full public install PDF and videos. Slightly notchier feel by design.", "price": "$280–330", "signal": "Forum favorite · best documented", "links": [{"store": "Dieselgeek (install guide linked on page)", "url": "https://dieselgeek.com/products/sigma-6-six-speed-short-shift-kit-for-vw"}]}, {"name": "VF Engineering / 42 Draft Designs", "note": "Transmission-side short-shift brackets of the same idea; less documentation available.", "price": "$200–300", "signal": "Alternatives", "links": []}, {"name": "Weighted shift knob (Raceseng, BFI)", "note": "Not a shifter, but the other half of the feel. Adds mass to the throw so it falls into gear.", "price": "$80–200", "signal": "Pairs well", "links": []}], "tools": [{"name": "Engine cover/airbox off (see air filter guide); 13mm and 10mm sockets; small flat screwdriver and needle-nose pliers for the cable-end clips"}, {"name": "Trim tool for the cabin shifter surround; the kit's transmission locking pin and shifter pin (or a drill bit of the size the PDF specifies)"}, {"name": "Grease, zip ties, the install PDF printed"}], "before": ["Car in neutral, parking brake on.", "Print the kit's PDF. This guide is the map; the PDF has the photos and the adjustment procedure specific to the kit.", "Do the bushing wiggle test first."], "steps": [{"n": 1, "title": "Room to work", "blocks": [{"t": "text", "b": "Engine cover/airbox off (air filter guide). The two shift cables run from the firewall to the top of the transmission on the driver's side; you now have a clear view."}]}, {"n": 2, "title": "Unclip the cables from the levers", "blocks": [{"t": "text", "b": "Two levers on the transmission: the selector (front-to-back) and the relay lever (side-to-side). Each cable end sits on a lever pin with a retaining clip. Lift the spring tab, slide the clip off, lift the cable end off the pin. The relay-lever end may need a gentle pry with needle-nose pliers."}, {"t": "ill", "id": "shifter-hero", "cap": "Selector lever (the one the kit replaces) and relay lever, each with a cable on a pin and a clip."}]}, {"n": 3, "title": "Stock lever off, kit lever on", "blocks": [{"t": "text", "b": "Remove the nut on the selector shaft (13mm) and lift the factory selector lever off the splined shaft; wiggle, don't hammer or pry the shaft. Note the double tooth on the splines: the lever only goes on one way. Fit the kit's shorter lever the same way and torque its nut per the PDF (the factory figure is 20 Nm)."}, {"t": "torque", "label": "Selector shaft nut", "nm": 20, "c": {"level": "medium", "n": 2, "note": "20 Nm factory value (ECS transmission guide); Dieselgeek's PDF governs their hardware."}}]}, {"n": 4, "title": "New cable ends", "blocks": [{"t": "text", "b": "Slide the kit's cable ends onto the cables until the threads disappear inside the end; slide each on and off a couple of times so it moves freely, then set it. Grease the ball on the new lever's pin and the cable-end socket. Press each cable end onto its pin and fit the clip."}]}, {"n": 5, "title": "Adjust", "caution": true, "blocks": [{"t": "text", "b": "Lock the transmission in neutral with the kit's locking pin (it goes into the hole beside the selector shaft; the PDF shows exactly where). Inside the car, pop the shifter surround, pull the boot down, and pin the cabin shifter in its neutral gate with the kit's pin. Now both ends are fixed. Release the cable adjusters (the locking collars on the cable sheaths at the transmission bracket), let the cables find their length, and re-lock the collars. Remove both pins."}, {"t": "warn", "b": "Everything about how this shifter feels is set here. If the adjusters were locked with tension on either cable, gears will be hard to find or will grind. Both pins in, cables relaxed, then lock. If it's notchy afterwards, redo this step; don't live with it."}, {"t": "note", "b": "Side-to-side cable preload: Dieselgeek's PDF describes lightly pulling the cable out of its end before locking; their later guidance is that newer cars may not need it. Follow the current PDF for your kit, then adjust by feel if 1st/2nd is reluctant."}]}, {"n": 6, "title": "Test every gate, then reassemble", "blocks": [{"t": "text", "b": "Engine off, clutch in: select all six gears and reverse from neutral. Each should engage with the same effort and the shifter should self-centre to the 3–4 gate. Then with the engine running, clutch in, the same. Zip-tie the cables clear of anything hot or moving. Airbox back on, shifter surround back on."}]}, {"n": 7, "title": "Drive and re-adjust", "blocks": [{"t": "text", "b": "Drive it a few days. A slight notchiness is the kit; a grind or a missed gate is adjustment. Re-pin and re-adjust if needed."}]}], "alsoReplace": [{"name": "Shifter base bushings (cabin)", "why": "Worn bushings make any shifter sloppy and can prevent proper adjustment. Ten minutes with the surround already off."}, {"name": "Side-to-side cable end (aluminium)", "why": "Replaces the last rubber-isolated part in the linkage; Dieselgeek sells it as an add-on for a reason."}, {"name": "Weighted shift knob", "why": "You've got the boot down. Mass in the knob is the other half of the feel."}], "check": {"tab": "Is it the shifter?", "title": "Is the shifter the problem?", "illId": "shifter-hero", "illCap": "Slop in the cabin base and slop at the transmission feel similar from the driver's seat.", "rows": [{"see": "Knob wobbles side to side in neutral", "means": "Cabin shifter base bushings.", "do": "Bushings first; then decide on the kit."}, {"see": "Long throw but precise gates", "means": "Just the factory geometry.", "do": "Short shift kit."}, {"see": "Grind into 2nd or reverse, hard to find gates", "means": "Adjustment, or a clutch that isn't fully releasing.", "do": "Re-adjust cables; bleed the clutch; if it persists, synchro."}], "c": {"level": "community", "n": 3, "note": "Vendor guidance and forum diagnosis."}}, "aftercare": ["Re-check the cable clips after a week.", "Notchy 1–2 that doesn't settle: re-adjust, and consider the side-to-side preload note."], "disagreements": [{"topic": "Preload the side-to-side cable?", "pos": "The PDF says yes; Dieselgeek later said newer cars may not need it.", "call": "Follow the current PDF, then by feel."}, {"topic": "Is notchy normal?", "pos": "Some owners expected a smoother shifter.", "call": "Yes; the vendor says so. Precision, not butter."}], "sources": ["Dieselgeek Sigma 6 product page and install guide", "VWVortex 'DIY – Dieselgeek Sigma Six Speed Short Shifter Install'", "VWVortex / Golfmk7 Sigma 6 install thread (same transmission)", "ECS 02Q transmission guide (selector shaft nut torque)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('battery',$j${"id": "battery", "title": "Battery replacement", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "battery-hero", "alsoFits": "All Mk5 platform cars (Golf, GTI, Jetta, Eos, A3); no battery coding on this generation", "category": "Electrical", "kind": "repair", "glance": {"timeFirst": "30 min", "timeRepeat": "15 min", "difficulty": 1, "cost": "$150–350", "risk": "Negative off first, on last · battery is heavy · acid", "why": "A weak battery on a modern VW does strange things before it dies: random warning lights, a DSG that acts up, a radio that resets. Five years is a fair life; if yours is older or the car has been slow to crank on a cold morning, this is a half-hour job with one rule that matters.", "note": "No coding is needed on a Mk5, which is the whole reason this is easy. Later cars differ."}, "heroCap": "Battery under a plastic cover on the driver's side. Negative terminal off first, hold-down clamp at the base, lift it out. Group H6 (also called 48 or L3).", "lifespan": {"title": "When to expect it", "headline": ["Typically 4–6 years; sooner in hot climates"], "earliest": "3 years in the desert Southwest", "detail": "Slow cranking on a cold start, a dash that flickers on crank, or a jump start you needed once are the warnings. Any parts store will load-test it for free; below about 12.4 V resting, or a failed load test, replace it before it strands you or corrupts a module with low voltage.", "factors": ["Heat", "Short trips (never fully charged)", "Parasitic drain from an aftermarket stereo or alarm", "Sitting for weeks"], "inspect": ["Resting voltage once a season: 12.6 V is healthy, 12.4 is tired, 12.2 is done"], "confidence": {"level": "community", "n": 3, "note": "General practice; consistent."}}, "should": {"yesIf": ["Slow crank, especially cold", "Failed a load test or reads under 12.4 V rested", "Date sticker says 5+ years", "Odd electrical gremlins that come and go"], "codes": [], "notes": ["Size: Group H6 (DIN L3 / BCI 48). The Mk5 GTI's tray and hold-down are made for it. Optima's H6 is the DH6; Odyssey's is the 48-720.", "AGM or flooded: both work on a Mk5 because it has no battery management module that needs to be told. AGM tolerates heat and vibration better and costs more. Either is fine; AGM is the upgrade.", "Radio codes: most Mk5 head units don't ask for one, but check your manual or glovebox card before you disconnect. A cheap memory saver plugged into the OBD port avoids the question entirely."], "confidence": {"level": "high", "n": 3, "note": "Fitment and the no-coding point are consistent across sources; AGM guidance is standard practice."}}, "parts": [{"tier": "oe", "name": "Battery, Group H6 (L3/48), flooded or AGM", "pn": "e.g. Varta, Bosch, Interstate H6", "note": "12V, ~70 Ah, 700+ CCA", "price": "$150–250", "links": []}, {"tier": "oe", "name": "Terminal protector spray or grease, felt washers", "pn": "—", "note": "", "price": "$8", "links": []}], "aftermarket": [{"name": "Optima RedTop DH6", "note": "AGM, spiral cell, high cranking amps, very vibration resistant. The forum's default upgrade.", "price": "$280–350", "signal": "Forum favorite", "links": []}, {"name": "Optima YellowTop DH6", "note": "Deep-cycle AGM for cars with big stereos or lots of accessories; same case.", "price": "$300–360", "signal": "For accessory-heavy cars", "links": []}, {"name": "Odyssey 48-720 (Extreme)", "note": "AGM with a long warranty and excellent heat tolerance. Slightly taller; check the cover clears.", "price": "$300–380", "signal": "Longevity pick", "links": []}, {"name": "Varta / Bosch AGM H6", "note": "OE-supplier AGM at a friendlier price. Same battery as many factory fits.", "price": "$200–260", "signal": "Value AGM", "links": []}], "tools": [{"name": "10mm wrench (terminals), 13mm socket with extension (hold-down)"}, {"name": "Terminal brush, gloves, safety glasses"}, {"name": "Optional: OBD memory saver; multimeter"}], "before": ["Engine off, key out of the ignition, windows closed (you'll relearn one-touch afterwards).", "Note your radio code if your head unit has one.", "Negative terminal comes off first and goes on last. Every time."], "steps": [{"n": 1, "title": "Cover off", "blocks": [{"t": "text", "b": "Push the release tab on the battery cover, pivot it up and unhook it at the rear."}]}, {"n": 2, "title": "Negative, then positive", "caution": true, "blocks": [{"t": "text", "b": "10mm: loosen the negative (black, marked −) clamp nut, twist the clamp off the post and tuck the cable where it can't touch the terminal. Then the positive (red, under its flip cover)."}, {"t": "warn", "b": "Negative first. If the wrench touches the body while you're on the positive terminal with the negative still connected, you've made a welder. Glasses on; batteries vent hydrogen."}, {"t": "ill", "id": "battery-hero", "cap": "Order: negative off, positive off, clamp, lift. Reverse to install."}]}, {"n": 3, "title": "Hold-down and lift", "blocks": [{"t": "text", "b": "13mm on an extension: the hold-down clamp bolt at the base of the battery, on the inboard side. Remove the clamp. If the front half of the battery box is in the way, lift it off. Lift the battery straight up and out; it's about 45 lb and awkward. Keep it level."}]}, {"n": 4, "title": "Clean and drop in", "blocks": [{"t": "text", "b": "Brush the terminal clamps clean inside. Check the tray for acid crust and wipe it. New battery in, same orientation (positive toward the front, matching the cables), seated in the tray's lip. Hold-down clamp back on and snug: it should not rock, but you're clamping plastic, so don't crank it."}]}, {"n": 5, "title": "Positive, then negative", "blocks": [{"t": "text", "b": "Positive clamp on its post first, nut snug (10mm; snug, the clamps distort if over-tightened). Then the negative. A wipe of terminal protector on both. Box half and cover back on."}]}, {"n": 6, "title": "Relearn the little things", "blocks": [{"t": "text", "b": "Start it. Set the clock. One-touch windows: close each window fully and hold the switch up for a second more, then open fully and hold down a second; repeat for each. Turn the steering wheel lock to lock once so the steering-angle sensor recentres (clears the ESP light if it's on). Sunroof: hold close until it cycles. That's it; no coding on this car."}]}], "alsoReplace": [{"name": "Ground strap and terminal clamps", "why": "Green or crusty clamps cause the same symptoms as a bad battery. A new clamp is $10."}, {"name": "Check the alternator", "why": "With the new battery in and the engine running, you should see 13.8–14.4 V at the terminals. If not, the battery wasn't the problem."}], "check": {"tab": "Test first", "title": "Is it the battery?", "illId": "battery-hero", "illCap": "A multimeter answers most of this.", "rows": [{"see": "Rested voltage 12.6+, cranks fine", "means": "Battery is fine.", "do": "Look elsewhere for your symptom."}, {"see": "Rested 12.2–12.4, slow crank", "means": "Tired.", "do": "Load test; probably replace."}, {"see": "13.8–14.4 V running", "means": "Alternator is fine.", "do": "Battery only."}, {"see": "Under 13.5 V running, or over 15", "means": "Charging problem.", "do": "Alternator or regulator; a new battery will just die again."}], "c": {"level": "high", "n": 3, "note": "Standard electrical diagnosis."}}, "aftercare": ["Write the install date on the battery with a marker.", "Recycle the old one; the store credits the core."], "disagreements": [{"topic": "Does it need coding?", "pos": "Newer VWs do; people assume all do.", "call": "Not the Mk5. Plug and play."}, {"topic": "AGM or flooded?", "pos": "Forum arguments about cost.", "call": "Both work here; AGM is the nicer part if the budget allows."}], "sources": ["ECS 02Q transmission guide (battery removal steps and fastener sizes)", "Optima / Odyssey fitment listings", "Forum consensus on Mk5 relearn procedures and the absence of battery coding"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('headlights',$j${"id": "headlights", "title": "Headlight bulbs & housings", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "headlight-hero", "alsoFits": "2006–09 GTI (halogen and bi-xenon); Golf/Rabbit and Jetta share the technique, not the housings", "category": "Electrical", "kind": "repair", "variants": {"question": "Which headlights does your car have?", "hint": "US Mk5 GTIs came both ways. Bi-xenon housings have a projector with a bluish-white beam and a small inner halogen; halogen housings use two ordinary reflector bulbs.", "options": [{"id": "halogen", "label": "Halogen", "when": "H7 bulbs, yellow-white light, cheap to replace"}, {"id": "xenon", "label": "Bi-xenon (HID)", "when": "One D2S bulb does low and high via a shutter; ~$50 each"}]}, "glance": {"timeFirst": "1–1.5 hr (assembly out) · 20 min if you can reach in", "timeRepeat": "30 min", "difficulty": 2, "cost": "$20–40 halogen · $80–120 xenon pair · $300+ per housing", "risk": "HID ballast voltage · scratching the bumper · touching halogen glass", "why": "Bulbs dim before they die, and one dead low beam is a ticket. On this car the honest way to change either bulb type is to take the headlight out, which means loosening the bumper cover. It sounds worse than it is, and while it's out you can fix the fogged lens or swap the whole housing.", "note": "Pelican and the forums agree: possible in place with small hands on the passenger side, painful on the driver's side, easy with the assembly out."}, "heroCap": "Headlight held by screws that hide behind the bumper cover's top edge. Loosen the cover, unscrew the housing, pull it forward, and every bulb cap is in front of you.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Halogen H7 low beams: typically 1–3 years of nightly use", "only": ["halogen"]}, {"text": "D2S xenon bulbs: typically 5–8 years; they dim and shift colour rather than fail suddenly", "only": ["xenon"]}], "earliest": "Cheap 'blue' halogens can go in months", "detail": "Halogens burn out; xenons fade toward purple and lose output long before they quit. Replace xenons in pairs so the colours match, and because the second one is close behind. Housings themselves go hazy from UV on the outside (polish) or from a failed seal on the inside (replace).", "factors": ["Daytime running lights on all the time", "Vibration from a rough road", "Touching halogen glass on install"], "inspect": ["Look at your low beams on a garage wall once a year: colour match and pattern"], "confidence": {"level": "community", "n": 3, "note": "Owner experience; no factory interval."}}, "should": {"yesIf": ["Low beam out, or the dash says 'dipped beam'", "Beams noticeably different colours (xenon)", "Lens fogged inside or badly hazed", "You want to upgrade housings"], "codes": [], "notes": [{"text": "H7 for the low beam. Most Mk5 GTI halogen housings also use H7 for the high beam, but confirm by reading the old bulb's base before you buy. Any decent brand (Osram, Philips) beats a blue-tinted 'upgrade' bulb, which is dimmer and short-lived.", "only": ["halogen"]}, {"text": "The outer projector's single D2S bulb does both low and high beam; a shutter moves for high. The small inner lamp is an H7 'flash to pass' that some owners code to act as an extra high beam. When the dash complains about the low beam, it's the D2S. Buy a name brand (Philips, Osram) and replace both sides.", "only": ["xenon"]}, {"text": "The ballast makes several thousand volts to light a D2S. Battery disconnected, lights off, and never operate a ballast with the bulb out.", "only": ["xenon"]}, "LED 'H7 replacement' bulbs in halogen reflector housings scatter light and blind other drivers; most aren't legal for road use. A better halogen is the honest upgrade for a reflector; a housing swap to bi-xenon is the real one."], "confidence": {"level": "medium", "n": 3, "note": "Pelican article and forum threads; bulb-type detail confirmed for xenon, halogen high beam noted as 'confirm on the old bulb'."}}, "parts": [{"tier": "oe", "name": "H7 halogen bulbs (pair)", "pn": "Osram Night Breaker / Philips X-tremeVision", "note": "Replace in pairs", "price": "$20–40", "links": [], "only": ["halogen"]}, {"tier": "oe", "name": "D2S xenon bulbs (pair)", "pn": "Philips 85122 / Osram 66240", "note": "Replace in pairs; name brand only", "price": "$80–120", "links": [], "only": ["xenon"]}, {"tier": "oe", "name": "Headlight housing (each), if replacing", "pn": "halogen or bi-xenon by VIN", "note": "OE (Hella) or OE-supplier; aftermarket varies widely", "price": "$300–900", "links": []}, {"tier": "oe", "name": "Bumper cover clips/screws", "pn": "a few break every time", "note": "", "price": "$10", "links": []}], "aftermarket": [{"name": "OEM-style bi-xenon housings (Hella)", "note": "The real upgrade for a halogen car: projector beam, proper cutoff, and legal. Needs the xenon wiring/ballasts or a harness, plus the auto-levelling if you want it correct.", "price": "$700–1,200 / pair", "signal": "The proper upgrade", "links": []}, {"name": "Depo / TYC replacement housings", "note": "Budget replacements for a fogged or cracked lens. Fit varies; beam quality is fine for halogen, hit-and-miss for projectors.", "price": "$150–300 each", "signal": "Budget lens fix", "links": []}, {"name": "Osram Night Breaker / Philips X-treme H7", "note": "Brighter, whiter halogens that are still legal. Shorter life than standard.", "price": "$25–40 / pair", "signal": "Best legal halogen", "links": [], "only": ["halogen"]}], "tools": [{"name": "T25 and T30 Torx, 10mm socket, trim tool for bumper clips"}, {"name": "Nitrile gloves (halogen glass), a soft blanket to set the housing on"}, {"name": "Flashlight; a friend to hold the bumper corner"}], "before": ["Battery negative disconnected, especially for xenon.", "Don't touch halogen glass with bare fingers; the oil creates a hot spot and the bulb fails early. If you did, wipe it with alcohol.", "Lay a blanket on the fender edge; you'll rest the housing there."], "steps": [{"n": 1, "title": "Try the shortcut (passenger side, halogen)", "only": ["halogen"], "blocks": [{"t": "text", "b": "With the airbox snorkel out of the way, small hands can reach the low-beam cap on the passenger side from above: twist the round cap off, unplug the bulb, release its wire clip, swap it. If you can do both sides this way, you're done in twenty minutes. Most people can't reach the driver's side past the fuse box and battery; for that side, continue."}]}, {"n": 2, "title": "Loosen the bumper cover's top edge", "blocks": [{"t": "text", "b": "Behind the grille and along the top of the bumper cover: Torx screws into the radiator support (T25/T30) and clips. Remove the screws along the top and the ones in the wheel-arch liner at the bumper corner (T25) so the corner of the cover can be pulled forward a few inches. Pelican's advice is to just remove the cover entirely; it's another fifteen minutes and saves scratching it."}, {"t": "ill", "id": "headlight-hero", "cap": "The housing screws are behind the bumper cover's edge. Loosen the cover, and they're right there."}]}, {"n": 3, "title": "Headlight out", "blocks": [{"t": "text", "b": "With the cover pulled forward, the headlight mounting screws are visible (top edge and outer side). Remove them, unplug the main connector on the back of the housing, and slide the housing forward and out. Set it face-down on the blanket."}, {"t": "warn", "b": "Xenon: the ballast is on the housing. Don't unplug or plug anything with the lights on, and don't power a ballast without a bulb.", "only": ["xenon"]}]}, {"n": 4, "title": "Swap the bulbs", "blocks": [{"t": "text", "b": "Round caps on the back: twist off. Low beam H7: unplug, squeeze the wire retainer clip, lift the bulb out, new one in with the tab orientation matching, clip, plug, cap. High beam: same. Gloves on the glass.", "only": ["halogen"]}, {"t": "text", "b": "Remove the projector's rear cap, unplug the igniter connector from the D2S, release the bulb's retaining ring or clip, lift the bulb straight out without touching the glass, seat the new one in the same orientation, retainer, igniter, cap. Do the other side too; colours must match.", "only": ["xenon"]}, {"t": "text", "b": "While it's out: if the lens is hazy outside, polish it now with a headlight restoration kit; it's a hundred times easier on the bench. Moisture inside means a failed seal, and that's a housing, not a bulb."}]}, {"n": 5, "title": "Housing back in, cover back on", "blocks": [{"t": "text", "b": "Plug the housing in, slide it into its locating pins, screws in. Bumper cover corner back, screws and clips. Battery negative reconnected."}]}, {"n": 6, "title": "Aim check", "blocks": [{"t": "text", "b": "Park 25 feet from a wall on level ground. Low-beam cutoffs should be level with each other and just below headlight height. Adjusters are on the back of the housing (T-handle or hex). Xenon cars with auto-levelling: turn the car on and watch the beams settle; if one stays low, the level sensor arm on the control arm is disconnected."}]}], "alsoReplace": [{"name": "Turn signal and DRL bulbs", "why": "Same housing, same trip. The amber bulbs fade and the sockets corrode."}, {"name": "Lens restoration", "why": "Housing on a bench is when to polish and UV-coat it."}, {"name": "Headlight washer nozzle / level sensor check", "why": "Xenon cars: while the bumper corner is loose, check the washer hose and that the level sensor arm is attached.", "only": ["xenon"]}], "check": {"tab": "Bulb or housing?", "title": "Bulb, housing, or something else?", "illId": "headlight-hero", "illCap": "Colour, moisture and the dash message narrow it quickly.", "rows": [{"see": "One low beam out, dash message", "means": "Bulb (D2S on xenon, H7 on halogen).", "do": "Replace, in pairs."}, {"see": "Beam flickers or takes several tries to light (xenon)", "means": "Bulb at end of life, or the ballast/igniter.", "do": "New bulbs first; if it persists, ballast."}, {"see": "Fog inside the lens", "means": "Seal failed.", "do": "Housing, or a careful reseal."}, {"see": "Both dim, yellow lens", "means": "UV haze on the polycarbonate.", "do": "Polish and coat."}], "c": {"level": "community", "n": 3, "note": "Owner threads and vendor guidance."}}, "aftercare": ["Check aim after a week.", "Xenon colour mismatch that persists: the ballasts differ or one bulb is a different brand."], "disagreements": [{"topic": "Can you do it in place?", "pos": "Some owners manage the passenger side; Pelican says take the assembly out.", "call": "Try the shortcut on the passenger side; take it out for the driver's side and for any xenon."}, {"topic": "Halogen high-beam bulb type", "pos": "H7 on most; not confirmed from a factory table.", "call": "Read the old bulb."}, {"topic": "LED drop-ins", "pos": "Popular; cheap.", "call": "Not in a reflector housing. Glare, and not legal on the road."}], "sources": ["Pelican Parts Mk5 GTI headlight bulb and assembly article", "VWVortex 'GTI Headlight Bulb Replacement' (bi-xenon detail)", "Owner threads on in-place bulb access", "Bulb and housing listings"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
